def shoppingOffers(price: list[int], special: list[list[int]], needs: list[int]) -> int:
    memo = {}
    def dfs(cur_needs):
        key = tuple(cur_needs)
        if key in memo: return memo[key]
        cost = sum(p * n for p, n in zip(price, cur_needs))
        for sp in special:
            new_needs = [cur_needs[i] - sp[i] for i in range(len(price))]
            if all(x >= 0 for x in new_needs):
                cost = min(cost, sp[-1] + dfs(new_needs))
        memo[key] = cost
        return cost
    return dfs(needs)

